import axios from 'axios';

const getApiUrl = () => {
    const { apiUrl } = window['runConfig'] || {
        apiUrl: 'https://access.stage.redhat.com/subscriptions/link/api/',
    };
    return apiUrl;
};

const getOrderDetailsAsync = async (auth, url, signal) => {
  return auth.getToken().then((token) => {
    return axios.get(url, {
      headers: { Authorization: `Bearer ${token}` },
      withCredentials: true, // required to supply cookies on cross-site requests
      signal: signal,
    });
  });
};

const getPartnerOrderDetailsAsync = async (auth, partnerId, signal) => {
  const url = getApiUrl() + `${partnerId}/details`;
  return getOrderDetailsAsync(auth, url, signal);
};

const getVendorOrderDetailsAsync = async (auth, partnerId, linkToken, signal) => {
  const url = getApiUrl() + `isv/${partnerId}/order/${linkToken}`;
  console.log('vendorApiUrl : ', url);
  return getOrderDetailsAsync(auth, url, signal);
};

const linkPartnerOrderToAccountAsync = async (auth, partnerId, termsPdfId) => {
    console.debug(`Linking partner=${partnerId}, terms=${termsPdfId}`);

    return auth.getToken().then((token) => {
        return axios
            .post(
                getApiUrl() + `${partnerId}/link`,
                {},
                {
                    headers: { Authorization: `Bearer ${token}` },
                    params: {
                        termsPdfId: termsPdfId,
                        linkAllOrders: true, // no longer optional
                    },
                    withCredentials: true, // required to supply cookies on cross-site requests
                }
            );
    }).then((res) => res?.data?.linkSuccessful);
};

export { getPartnerOrderDetailsAsync, getVendorOrderDetailsAsync, linkPartnerOrderToAccountAsync };
